From decc67ab9b1dc7e138c1120c8f93d3107fc764fb Mon Sep 17 00:00:00 2001
From: Peyton Montei <peyton@entire.io>
Date: Wed, 15 Apr 2026 17:54:41 -0700
Subject: [PATCH 2/4] feat(claudecode): add ClaudeError typed error

Introduces a typed error so callers (specifically cli/explain.go) can map
structured Claude CLI failures to user-facing messages via errors.As. No
classifier logic yet; envelope and stderr classifiers follow in Task 4.

Co-Authored-By: Claude Opus 4.6 (1M context) <noreply@anthropic.com>
Entire-Checkpoint: 6901d9051456
---
 cmd/entire/cli/agent/claudecode/error.go      | 43 ++++++++++++
 cmd/entire/cli/agent/claudecode/error_test.go | 68 +++++++++++++++++++
 2 files changed, 111 insertions(+)
 create mode 100644 cmd/entire/cli/agent/claudecode/error.go
 create mode 100644 cmd/entire/cli/agent/claudecode/error_test.go

diff --git a/cmd/entire/cli/agent/claudecode/error.go b/cmd/entire/cli/agent/claudecode/error.go
new file mode 100644
index 000000000..d10a40b1c
--- /dev/null
+++ b/cmd/entire/cli/agent/claudecode/error.go
@@ -0,0 +1,43 @@
+package claudecode
+
+import "fmt"
+
+// ClaudeErrorKind classifies a typed Claude CLI error so callers can
+// produce actionable user-facing messages without parsing strings.
+type ClaudeErrorKind string
+
+const (
+	// ClaudeErrorAuth indicates an authentication or authorization failure
+	// (HTTP 401/403 in the CLI envelope, or recognized stderr substring).
+	ClaudeErrorAuth ClaudeErrorKind = "auth"
+	// ClaudeErrorRateLimit indicates the request was rejected for rate-limit
+	// or quota reasons (HTTP 429).
+	ClaudeErrorRateLimit ClaudeErrorKind = "rate_limit"
+	// ClaudeErrorConfig indicates a client-side request error other than
+	// auth or rate-limit (e.g., HTTP 4xx for invalid model or malformed args).
+	ClaudeErrorConfig ClaudeErrorKind = "config"
+	// ClaudeErrorCLIMissing indicates the claude binary was not found on PATH.
+	ClaudeErrorCLIMissing ClaudeErrorKind = "cli_missing"
+	// ClaudeErrorUnknown is the catch-all for failures we cannot classify.
+	ClaudeErrorUnknown ClaudeErrorKind = "unknown"
+)
+
+// ClaudeError is a typed error returned by ClaudeCodeAgent's text generation
+// methods. Callers can use errors.As to recover the kind and produce
+// user-facing messages.
+type ClaudeError struct {
+	Kind      ClaudeErrorKind
+	Message   string // user-safe text extracted from the CLI envelope or stderr
+	APIStatus int    // HTTP status from the envelope; 0 if not applicable
+	ExitCode  int    // subprocess exit code; 0 if not applicable
+	Cause     error
+}
+
+func (e *ClaudeError) Error() string {
+	if e.Message == "" {
+		return fmt.Sprintf("claude CLI error (kind=%s)", e.Kind)
+	}
+	return fmt.Sprintf("claude CLI error (kind=%s): %s", e.Kind, e.Message)
+}
+
+func (e *ClaudeError) Unwrap() error { return e.Cause }
diff --git a/cmd/entire/cli/agent/claudecode/error_test.go b/cmd/entire/cli/agent/claudecode/error_test.go
new file mode 100644
index 000000000..bc59c166e
--- /dev/null
+++ b/cmd/entire/cli/agent/claudecode/error_test.go
@@ -0,0 +1,68 @@
+package claudecode
+
+import (
+	"errors"
+	"fmt"
+	"strings"
+	"testing"
+)
+
+func TestClaudeError_ErrorIncludesKindAndMessage(t *testing.T) {
+	t.Parallel()
+	e := &ClaudeError{Kind: ClaudeErrorAuth, Message: "Invalid API key"}
+	s := e.Error()
+	if !strings.Contains(s, "auth") {
+		t.Errorf("Error() = %q; want to contain kind 'auth'", s)
+	}
+	if !strings.Contains(s, "Invalid API key") {
+		t.Errorf("Error() = %q; want to contain message", s)
+	}
+}
+
+func TestClaudeError_UnwrapReturnsCause(t *testing.T) {
+	t.Parallel()
+	cause := errors.New("underlying")
+	e := &ClaudeError{Kind: ClaudeErrorUnknown, Cause: cause}
+	if got := errors.Unwrap(e); !errors.Is(got, cause) {
+		t.Errorf("Unwrap() = %v; want %v", got, cause)
+	}
+}
+
+func TestClaudeError_UnwrapNilCause(t *testing.T) {
+	t.Parallel()
+	e := &ClaudeError{Kind: ClaudeErrorAuth}
+	if got := errors.Unwrap(e); got != nil {
+		t.Errorf("Unwrap() = %v; want nil", got)
+	}
+}
+
+func TestClaudeError_ErrorEmptyMessageFallback(t *testing.T) {
+	t.Parallel()
+	e := &ClaudeError{Kind: ClaudeErrorRateLimit}
+	s := e.Error()
+	want := "claude CLI error (kind=rate_limit)"
+	if s != want {
+		t.Errorf("Error() = %q; want %q", s, want)
+	}
+}
+
+func TestClaudeError_ErrorsAsIntegration(t *testing.T) {
+	t.Parallel()
+	cause := errors.New("timeout")
+	wrapped := fmt.Errorf("operation failed: %w", &ClaudeError{
+		Kind:    ClaudeErrorCLIMissing,
+		Message: "claude not found",
+		Cause:   cause,
+	})
+
+	var ce *ClaudeError
+	if !errors.As(wrapped, &ce) {
+		t.Fatal("errors.As did not find *ClaudeError in wrapped chain")
+	}
+	if ce.Kind != ClaudeErrorCLIMissing {
+		t.Errorf("Kind = %q; want %q", ce.Kind, ClaudeErrorCLIMissing)
+	}
+	if !errors.Is(ce, cause) {
+		t.Error("errors.Is did not find cause through ClaudeError.Unwrap()")
+	}
+}

From a589890831f2b14bafacf1bb954f873ee66a2b2b Mon Sep 17 00:00:00 2001
From: Peyton Montei <peyton@entire.io>
Date: Wed, 15 Apr 2026 18:13:40 -0700
Subject: [PATCH 3/4] feat(claudecode): classify envelope and stderr errors
 into ClaudeError

classifyEnvelopeError maps api_error_status (401/403 -> auth, 429 ->
rate_limit, other 4xx -> config, else unknown) for the structured
exit-0 failure path observed in the live CLI. classifyStderrError is a
small fallback for crashes that exit non-zero before producing an
envelope; matches a deliberately short auth-phrase list.

Co-Authored-By: Claude Opus 4.6 (1M context) <noreply@anthropic.com>
Entire-Checkpoint: 6ebe1c92ce0b
---
 cmd/entire/cli/agent/claudecode/error.go      |  61 +++++++-
 cmd/entire/cli/agent/claudecode/error_test.go | 134 ++++++++++++++++++
 2 files changed, 194 insertions(+), 1 deletion(-)

diff --git a/cmd/entire/cli/agent/claudecode/error.go b/cmd/entire/cli/agent/claudecode/error.go
index d10a40b1c..cb69d7fc4 100644
--- a/cmd/entire/cli/agent/claudecode/error.go
+++ b/cmd/entire/cli/agent/claudecode/error.go
@@ -1,6 +1,9 @@
 package claudecode

-import "fmt"
+import (
+	"fmt"
+	"strings"
+)

 // ClaudeErrorKind classifies a typed Claude CLI error so callers can
 // produce actionable user-facing messages without parsing strings.
@@ -41,3 +44,59 @@ func (e *ClaudeError) Error() string {
 }

 func (e *ClaudeError) Unwrap() error { return e.Cause }
+
+const stderrMessageMaxLen = 500
+
+// authStderrPhrases is intentionally small. The primary auth-detection path
+// is the structured envelope (classifyEnvelopeError); these phrases are a
+// best-effort fallback for crashes that exit non-zero before the envelope
+// is produced.
+var authStderrPhrases = []string{
+	"invalid api key",
+	"not logged in",
+}
+
+// classifyEnvelopeError converts a Claude CLI is_error:true envelope into a
+// typed ClaudeError. The result text is treated as user-safe (the CLI
+// produces it for human consumption).
+func classifyEnvelopeError(resultText string, apiStatus *int, exitCode int) *ClaudeError {
+	e := &ClaudeError{
+		Message:  resultText,
+		ExitCode: exitCode,
+	}
+	if apiStatus != nil {
+		e.APIStatus = *apiStatus
+	}
+	switch {
+	case e.APIStatus == 401, e.APIStatus == 403:
+		e.Kind = ClaudeErrorAuth
+	case e.APIStatus == 429:
+		e.Kind = ClaudeErrorRateLimit
+	case e.APIStatus >= 400 && e.APIStatus < 500:
+		e.Kind = ClaudeErrorConfig
+	default:
+		e.Kind = ClaudeErrorUnknown
+	}
+	return e
+}
+
+// classifyStderrError is a fallback classifier used when the subprocess exited
+// non-zero without producing a parseable envelope. It only attempts to
+// recognize a small, stable set of auth phrases; everything else becomes
+// ClaudeErrorUnknown with the (truncated) stderr as the message.
+func classifyStderrError(stderr string, exitCode int) *ClaudeError {
+	msg := strings.TrimSpace(stderr)
+	if len(msg) > stderrMessageMaxLen {
+		msg = msg[:stderrMessageMaxLen]
+	}
+	e := &ClaudeError{Message: msg, ExitCode: exitCode}
+	lower := strings.ToLower(msg)
+	for _, phrase := range authStderrPhrases {
+		if strings.Contains(lower, phrase) {
+			e.Kind = ClaudeErrorAuth
+			return e
+		}
+	}
+	e.Kind = ClaudeErrorUnknown
+	return e
+}
diff --git a/cmd/entire/cli/agent/claudecode/error_test.go b/cmd/entire/cli/agent/claudecode/error_test.go
index bc59c166e..391fc203c 100644
--- a/cmd/entire/cli/agent/claudecode/error_test.go
+++ b/cmd/entire/cli/agent/claudecode/error_test.go
@@ -66,3 +66,137 @@ func TestClaudeError_ErrorsAsIntegration(t *testing.T) {
 		t.Error("errors.Is did not find cause through ClaudeError.Unwrap()")
 	}
 }
+
+// --- Envelope classifier tests ---
+
+func TestClassifyEnvelopeError_Auth401(t *testing.T) {
+	t.Parallel()
+	status := 401
+	got := classifyEnvelopeError("Authentication required", &status, 0)
+	if got.Kind != ClaudeErrorAuth {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorAuth)
+	}
+	if got.Message != "Authentication required" {
+		t.Errorf("Message = %q; want envelope text", got.Message)
+	}
+	if got.APIStatus != 401 {
+		t.Errorf("APIStatus = %d; want 401", got.APIStatus)
+	}
+}
+
+func TestClassifyEnvelopeError_Auth403(t *testing.T) {
+	t.Parallel()
+	status := 403
+	got := classifyEnvelopeError("forbidden", &status, 0)
+	if got.Kind != ClaudeErrorAuth {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorAuth)
+	}
+}
+
+func TestClassifyEnvelopeError_RateLimit429(t *testing.T) {
+	t.Parallel()
+	status := 429
+	got := classifyEnvelopeError("Too many requests", &status, 0)
+	if got.Kind != ClaudeErrorRateLimit {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorRateLimit)
+	}
+}
+
+func TestClassifyEnvelopeError_Config404(t *testing.T) {
+	t.Parallel()
+	status := 404
+	got := classifyEnvelopeError("model not found", &status, 0)
+	if got.Kind != ClaudeErrorConfig {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorConfig)
+	}
+}
+
+func TestClassifyEnvelopeError_Config400(t *testing.T) {
+	t.Parallel()
+	status := 400
+	got := classifyEnvelopeError("invalid_request_error", &status, 0)
+	if got.Kind != ClaudeErrorConfig {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorConfig)
+	}
+}
+
+func TestClassifyEnvelopeError_UnknownNoStatus(t *testing.T) {
+	t.Parallel()
+	got := classifyEnvelopeError("something blew up", nil, 0)
+	if got.Kind != ClaudeErrorUnknown {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorUnknown)
+	}
+	if got.Message != "something blew up" {
+		t.Errorf("Message = %q; want envelope text", got.Message)
+	}
+}
+
+func TestClassifyEnvelopeError_Unknown5xx(t *testing.T) {
+	t.Parallel()
+	status := 503
+	got := classifyEnvelopeError("upstream error", &status, 0)
+	if got.Kind != ClaudeErrorUnknown {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorUnknown)
+	}
+}
+
+func TestClassifyEnvelopeError_ExitCodePropagated(t *testing.T) {
+	t.Parallel()
+	status := 500
+	got := classifyEnvelopeError("internal error", &status, 2)
+	if got.ExitCode != 2 {
+		t.Errorf("ExitCode = %d; want 2", got.ExitCode)
+	}
+}
+
+// --- Stderr classifier tests ---
+
+func TestClassifyStderrError_AuthFromInvalidKey(t *testing.T) {
+	t.Parallel()
+	got := classifyStderrError("error: Invalid API key", 1)
+	if got.Kind != ClaudeErrorAuth {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorAuth)
+	}
+	if got.ExitCode != 1 {
+		t.Errorf("ExitCode = %d; want 1", got.ExitCode)
+	}
+}
+
+func TestClassifyStderrError_AuthFromNotLoggedIn(t *testing.T) {
+	t.Parallel()
+	got := classifyStderrError("Please run claude login first; you are not logged in", 1)
+	if got.Kind != ClaudeErrorAuth {
+		t.Errorf("Kind = %v; want %v", got.Kind, ClaudeErrorAuth)
+	}
+}
+
+func TestClassifyStderrError_AuthCaseInsensitive(t *testing.T) {
+	t.Parallel()
+	got := classifyStderrError("INVALID API KEY", 1)
+	if got.Kind != ClaudeErrorAuth {
+		t.Errorf("Kind = %v; want %v for case-insensitive match", got.Kind, ClaudeErrorAuth)
+	}
+}
+
+func TestClassifyStderrError_UnknownPreservesMessage(t *testing.T) {
+	t.Parallel()
