321				input:    "```\n{\"key\": \"value\"}\n```",
322				expected: `{"key": "value"}`,
323			},
324			{
325				name:     "with whitespace",
326				input:    "  \n```json\n{\"key\": \"value\"}\n```  \n",
327				expected: `{"key": "value"}`,
328			},
329			{
330				name:     "unclosed block",
331				input:    "```json\n{\"key\": \"value\"}",
332				expected: `{"key": "value"}`,
333			},
334		}
335	
336		for _, tt := range tests {
337			t.Run(tt.name, func(t *testing.T) {
338				t.Parallel()
339				result := extractJSONFromMarkdown(tt.input)
340				if result != tt.expected {
341					t.Errorf("expected %q, got %q", tt.expected, result)
342				}
343			})
344		}
345	}
346

