1	// Package summarize provides AI-powered summarization of development sessions.
2	package summarize
3	
4	import (
5		"bytes"
6		"context"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"strings"
11	
12		"github.com/entireio/cli/cmd/entire/cli/agent"
13		"github.com/entireio/cli/cmd/entire/cli/agent/factoryaidroid"
14		"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
15		"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
16		"github.com/entireio/cli/cmd/entire/cli/agent/types"
17		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
18		"github.com/entireio/cli/cmd/entire/cli/transcript"
19		"github.com/entireio/cli/cmd/entire/cli/transcript/compact"
20		"github.com/entireio/cli/redact"
21	)
22	
23	// GenerateFromTranscript generates a summary from pre-redacted transcript bytes.
24	// This is the shared implementation used by both explain --generate and auto-summarize.
25	//
26	// Parameters:
27	//   - ctx: context for cancellation
28	//   - transcriptBytes: pre-redacted transcript (JSONL or JSON format depending on agent)
29	//   - filesTouched: list of files modified during the session
30	//   - agentType: the agent type to determine transcript format
31	//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
32	//
33	// Returns nil, error if transcript is empty or cannot be parsed.
34	func GenerateFromTranscript(ctx context.Context, transcriptBytes redact.RedactedBytes, filesTouched []string, agentType types.AgentType, generator Generator) (*checkpoint.Summary, error) {
35		if transcriptBytes.Len() == 0 {
36			return nil, errors.New("empty transcript")
37		}
38	
39		// Build condensed transcript for summarization
40		condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
41		if err != nil {
42			return nil, fmt.Errorf("failed to parse transcript: %w", err)
43		}
44		if len(condensed) == 0 {
45			return nil, errors.New("transcript has no content to summarize")
46		}
47	
48		input := Input{
49			Transcript:   condensed,
50			FilesTouched: filesTouched,
51		}
52	
53		if generator == nil {
54			generator = &ClaudeGenerator{}
55		}
56	
57		summary, err := generator.Generate(ctx, input)
58		if err != nil {
59			return nil, err //nolint:wrapcheck // preserve *ClaudeError for errors.As at the explain layer
60		}
61	
62		return summary, nil
63	}
64	
65	// Generator generates checkpoint summaries using an LLM.
66	type Generator interface {
67		// Generate creates a summary from checkpoint data.
68		// Returns the generated summary or an error if generation fails.
69		Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
70	}
71	
72	// Input contains condensed checkpoint data for summarization.
73	type Input struct {
74		// Transcript is the condensed transcript entries
75		Transcript []Entry
76	
77		// FilesTouched are the files modified during the session
78		FilesTouched []string
79	}
80	
81	// EntryType represents the type of a transcript entry.
82	type EntryType string
83	
84	const (
85		// EntryTypeUser indicates a user prompt entry.
86		EntryTypeUser EntryType = "user"
87		// EntryTypeAssistant indicates an assistant response entry.
88		EntryTypeAssistant EntryType = "assistant"
89		// EntryTypeTool indicates a tool call entry.
90		EntryTypeTool EntryType = "tool"
91	)
92	
93	// Entry represents one item in the condensed transcript.
94	type Entry struct {
95		// Type is the entry type (user, assistant, tool)
96		Type EntryType
97	
98		// Content is the text content for user/assistant entries
99		Content string
100	
101		// ToolName is the name of the tool (for tool entries)
102		ToolName string
103	
104		// ToolDetail is a description or file path (for tool entries)
105		ToolDetail string
106	}
107	
108	// minimalDetailTools lists tools that should show only essential details in summaries.
109	// These tools often have verbose outputs that don't add value to summarization.
110	// The detail shown is typically just a path, URL, or identifier rather than full content.
111	var minimalDetailTools = map[string]bool{
112		"Skill":    true, // Show skill name only, not loaded content
113		"Read":     true, // Show file path only, not file contents
114		"WebFetch": true, // Show URL only, not fetched content
115	}
116	
117	// BuildCondensedTranscriptFromBytes parses pre-redacted transcript bytes and extracts a condensed view.
118	// This is a convenience function that combines parsing and condensing.
119	// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
120	func BuildCondensedTranscriptFromBytes(content redact.RedactedBytes, agentType types.AgentType) ([]Entry, error) {
121		switch agentType {
122		case agent.AgentTypeGemini:
123			return buildCondensedTranscriptFromGemini(content)
124		case agent.AgentTypeFactoryAIDroid:
125			return buildCondensedTranscriptFromDroid(content)
126		case agent.AgentTypeOpenCode:
127			return buildCondensedTranscriptFromOpenCode(content)
128		case agent.AgentTypeCodex:
129			return buildCondensedTranscriptFromCodex(content)
130		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
131			// Claude/cursor format - fall through to shared logic below
132		}
133		// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
134		lines, err := transcript.ParseFromBytes(content.Bytes())
135		if err != nil {
136			return nil, fmt.Errorf("failed to parse transcript: %w", err)
137		}
138		return BuildCondensedTranscript(lines), nil
139	}
140	
141	// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
142	func buildCondensedTranscriptFromGemini(redacted redact.RedactedBytes) ([]Entry, error) {
143		geminiTranscript, err := geminicli.ParseTranscript(redacted.Bytes())
144		if err != nil {
145			return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
146		}
147	
148		var entries []Entry
149		for _, msg := range geminiTranscript.Messages {
150			switch msg.Type {
151			case geminicli.MessageTypeUser:
152				if msg.Content != "" {
153					entries = append(entries, Entry{
154						Type:    EntryTypeUser,
155						Content: msg.Content,
156					})
157				}
158			case geminicli.MessageTypeGemini:
159				// Add assistant content
160				if msg.Content != "" {
161					entries = append(entries, Entry{
162						Type:    EntryTypeAssistant,
163						Content: msg.Content,
164					})
165				}
166				// Add tool calls
167				for _, tc := range msg.ToolCalls {
168					entries = append(entries, Entry{
169						Type:       EntryTypeTool,
170						ToolName:   tc.Name,
171						ToolDetail: extractGenericToolDetail(tc.Args),
172					})
173				}
174			}
175		}
176	
177		return entries, nil
178	}
179	
180	// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
181	func buildCondensedTranscriptFromOpenCode(redacted redact.RedactedBytes) ([]Entry, error) {
182		session, err := opencode.ParseExportSession(redacted.Bytes())
183		if err != nil {
184			return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
185		}
186		if session == nil {
187			return nil, nil
188		}
189	
190		var entries []Entry
191		for _, msg := range session.Messages {
192			switch msg.Info.Role {
193			case "user":
194				text := opencode.ExtractTextFromParts(msg.Parts)
195				if text != "" {
196					entries = append(entries, Entry{
197						Type:    EntryTypeUser,
198						Content: text,
199					})
200				}
201			case "assistant":
202				text := opencode.ExtractTextFromParts(msg.Parts)
203				if text != "" {
204					entries = append(entries, Entry{
205						Type:    EntryTypeAssistant,
206						Content: text,
207					})
208				}
209				for _, part := range msg.Parts {
210					if part.Type == "tool" && part.State != nil {
211						entries = append(entries, Entry{
212							Type:       EntryTypeTool,
213							ToolName:   part.Tool,
214							ToolDetail: extractOpenCodeToolDetail(part.State.Input),
215						})
216					}
217				}
218			}
219		}
220	
221		return entries, nil
222	}
223	
224	// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
225	// transcript format, then reuses the shared transcript condensation logic.
226	func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
227		compacted, err := compact.Compact(content, compact.MetadataFields{
228			Agent:      "codex",
229			CLIVersion: "summarize",
230		})
231		if err != nil {
232			return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
233		}
234	
235		type compactUserTextBlock struct {
236			Text string `json:"text"`
237		}
238		type compactAssistantBlock struct {
239			Type  string          `json:"type"`
240			Text  string          `json:"text,omitempty"`
241			Name  string          `json:"name,omitempty"`
242			Input json.RawMessage `json:"input,omitempty"`
243		}
244		type compactLine struct {
245			Type    string          `json:"type"`
246			Content json.RawMessage `json:"content"`
247		}
248	
249		var entries []Entry
250		for _, lineBytes := range splitCompactJSONL(compacted) {
251			var line compactLine
252			if err := json.Unmarshal(lineBytes, &line); err != nil {
253				continue
254			}
255	
256			switch line.Type {
257			case transcript.TypeUser:
258				var blocks []compactUserTextBlock
259				if err := json.Unmarshal(line.Content, &blocks); err != nil {
260					continue
261				}
262				for _, block := range blocks {
263					if block.Text != "" {
264						entries = append(entries, Entry{
265							Type:    EntryTypeUser,
266							Content: block.Text,
267						})
268					}
269				}
270			case transcript.TypeAssistant:
271				var blocks []compactAssistantBlock
272				if err := json.Unmarshal(line.Content, &blocks); err != nil {
273					continue
274				}
275				for _, block := range blocks {
276					switch block.Type {
277					case transcript.ContentTypeText:
278						if block.Text != "" {
279							entries = append(entries, Entry{
280								Type:    EntryTypeAssistant,
281								Content: block.Text,
282							})
283						}
284					case transcript.ContentTypeToolUse:
285						var input map[string]interface{}
286						if err := json.Unmarshal(block.Input, &input); err != nil {
287							input = nil
288						}
289						entries = append(entries, Entry{
290							Type:       EntryTypeTool,
291							ToolName:   block.Name,
292							ToolDetail: extractGenericToolDetail(input),
293						})
294					}
295				}
296			}
297		}
298	
299		return entries, nil
300	}
301	
302	// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
303	func buildCondensedTranscriptFromDroid(redacted redact.RedactedBytes) ([]Entry, error) {
304		droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(redacted.Bytes(), 0)
305		if err != nil {
306			return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
307		}
308		return BuildCondensedTranscript(droidLines), nil
309	}
310	
311	// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
312	// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
313	func extractOpenCodeToolDetail(input map[string]interface{}) string {
314		for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
315			if v, ok := input[key].(string); ok && v != "" {
316				return v
317			}
318		}
319		return ""
320	}
321	
322	// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
323	// Checks common fields in order of preference. Used by Gemini condensation.
324	func extractGenericToolDetail(input map[string]interface{}) string {
325		if input == nil {
326			return ""
327		}
328		for _, key := range []string{"description", "command", "cmd", "file_path", "path", "pattern"} {
329			if v, ok := input[key].(string); ok && v != "" {
330				return v
331			}
332		}
333		return ""
334	}
335	
336	func splitCompactJSONL(data []byte) [][]byte {
337		var lines [][]byte
338		for _, line := range bytes.Split(data, []byte("\n")) {
339			line = bytes.TrimSpace(line)
340			if len(line) > 0 {
341				lines = append(lines, line)
342			}
343		}
344		return lines
345	}
346	
347	// BuildCondensedTranscript extracts a condensed view of the transcript.
348	// It processes user prompts, assistant responses, and tool calls into
349	// a simplified format suitable for LLM summarization.
350	func BuildCondensedTranscript(lines []transcript.Line) []Entry {
351		var entries []Entry
352	
353		for _, line := range lines {
354			switch line.Type {
355			case transcript.TypeUser:
